+import { consume } from "./batches.js";
+import { getDish } from "./menu.js";
+import { getRecipe, scaled } from "./recipes.js";
+
+/** Records one sale and consumes its ingredient quantities at the sale instant. */
+export function recordSale(store, { ticket, soldAt, dishId, qty }) {
+  const dish = getDish(store, dishId);
+  const ingredients = scaled(getRecipe(store, dish.recipeId), qty);
+  for (const ingredient of ingredients) {
+    if (ingredient.qty > 0)
+      consume(store, ingredient.itemId, ingredient.qty, { at: soldAt, ref: `sale:${ticket}` });
+  }
+  const sale = { id: store.nextId("sale"), ticket, soldAt, dishId, qty, ingredients };
+  store.data.sales.push(sale);
+  return sale;
+}
